import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        nextInt(); // n
        long[] a = new long[16];
        int m = 0;
        long total = 0;
        while (hasMore()) {
            if (m == a.length) a = Arrays.copyOf(a, m * 2);
            a[m] = nextLong();
            total += a[m++];
        }
        // difference: best advantage of the lock holder over the other core
        long difference = 0;
        for (int i = m - 1; i >= 0; i--) difference = Math.abs(a[i] - difference);
        System.out.println((total + difference) / 2 + " " + (total - difference) / 2);
    }
}

