import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func hasMore() bool {
	skip()
	return pos < len(data)
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	nextInt() // n
	var a []int64
	var total int64
	for hasMore() {
		v := nextInt()
		a = append(a, v)
		total += v
	}
	// difference: best advantage of the lock holder over the other core
	var difference int64
	for i := len(a) - 1; i >= 0; i-- {
		difference = a[i] - difference
		if difference < 0 {
			difference = -difference
		}
	}
	fmt.Println((total+difference)/2, (total-difference)/2)
}
